// ISC 12 Mathematics ch14 Three-Dimensional Geometry: Lines — practice bank with independent re-solve checks.
// Every point and direction printed in a stem is a constant below; every printed answer (direction cosines,
// angles, equations, intersection points, feet of perpendiculars, distances) is generated from those constants
// with vec.mjs, and each check recomputes it a second way: points are substituted back into both lines, feet are
// tested for lying on the line with a perpendicular joining vector, and shortest distances by formula are
// compared with a numeric minimisation of the distance between moving points. Planes are ch15 and appear nowhere.
// All set-ups are SOYL's own (D-036): drone paths, ropeways, laser beams, cable runs and tunnels are imagined.
import { Q, mk } from '../../isc-12-mathematics-ch01/src/lib.mjs';
import { sub, add, mul, dot, cross, norm, dcs, near, eqv, parallel, angleDeg, at, onLine, foot, sdFormula, sdNumeric, intersect, vtex, lineVec, cart, pt } from './vec.mjs';

/** String.raw, except that a backslash-n not followed by a lower-case letter becomes a newline. */
const r = (s, ...v) => String.raw(s, ...v).replace(/\\n(?![a-z])/g, '\n');
export const must = (cond, msg) => { if (!cond) throw new Error(`questions self-check: ${msg}`); };
const gcd = (a, b) => (b === 0 ? Math.abs(a) : gcd(b, a % b));
/** Reduced fraction p/q as TeX. */
export function fr(p, q = 1) {
  if (q < 0) { p = -p; q = -q; }
  const g = gcd(p, q) || 1;
  p /= g; q /= g;
  if (q === 1) return `${p}`;
  return `${p < 0 ? '-' : ''}\\dfrac{${Math.abs(p)}}{${q}}`;
}
/** Direction cosines of integer ratios u as TeX (integer length only). */
export function dcTex(u) {
  const n = Math.sqrt(dot(u, u));
  must(Number.isInteger(n), `length of ${u} is not an integer`);
  return u.map((x) => fr(x, n)).join(', ');
}
export const sumsq = (u) => dot(u, u);
/** Shortest distance, by formula, confirmed by numeric minimisation. */
export function sd(a1, b1, a2, b2) {
  const f = sdFormula(a1, b1, a2, b2), n = sdNumeric(a1, b1, a2, b2).d;
  must(near(f, n, 1e-6), `sd formula ${f} vs numeric ${n}`);
  return f;
}
const deg = (u, v) => Math.round(angleDeg(u, v) * 1e6) / 1e6;

// ================================================================ MCQ — t01 direction cosines and ratios; axes and coordinate planes
const m01A = [1, -2, 3], m01B = [5, 2, 1];
const m01d = sub(m01B, m01A); // (4, 4, -2) ~ (2, 2, -1), length 6
must(norm(m01d) === 6, 'm01');
Q('m01', mk.mcq({ stem: r`A survey drone climbs straight from a launch pad at $A(1, -2, 3)$ to a hovering point $B(5, 2, 1)$ (coordinates in metres). The direction cosines of its flight path $AB$ are`, opts: [r`$\dfrac23, \dfrac23, -\dfrac13$`, '$4, 4, -2$', r`$\dfrac23, \dfrac23, \dfrac13$`, r`$\dfrac13, \dfrac13, -\dfrac16$`], key: 'a', sol: r`$\vec{AB} = 4\hat{i} + 4\hat{j} - 2\hat{k}$ and $AB = \sqrt{16 + 16 + 4} = 6$; dividing gives $\dfrac46, \dfrac46, -\dfrac26$. Option (b) gives direction ratios, not cosines.`, d: 2, c: 'understanding', t: [1], time: 60 }), (C) => C.which([[2 / 3, 2 / 3, -1 / 3], [4, 4, -2], [2 / 3, 2 / 3, 1 / 3], [1 / 3, 1 / 3, -1 / 6]], dcs(m01d)));
const onZaxis = (p) => p[0] === 0 && p[1] === 0;
Q('m02', mk.mcq({ stem: r`A flagpole stands exactly along the $z$-axis of a school's coordinate model. Which pair of equations describes the line of the flagpole?`, opts: ['$x = 0$, $y = 0$', '$z = 0$', '$x = 0$, $z = 0$', '$x = y = z$'], key: 'a', sol: r`Every point of the $z$-axis has the form $(0, 0, t)$: both $x$ and $y$ are zero. A single equation $z = 0$ is a plane, and $x = 0$, $z = 0$ is the $y$-axis.`, d: 1, c: 'recall', t: [1], time: 30 }), (C) => { C.assert(onZaxis([0, 0, 7]) && onZaxis([0, 0, -2]) && !onZaxis([0, 3, 0]), 'z-axis points'); C.key('a'); });
Q('m03', mk.mcq({ stem: r`In a model of a hall, the floor is the $xy$-plane and one wall contains the $x$- and $z$-axes. Which equation describes the plane of that wall?`, opts: ['$y = 0$', '$x = 0$', '$z = 0$', '$x = z$'], key: 'a', sol: r`Points on the $x$-axis $(t, 0, 0)$ and the $z$-axis $(0, 0, s)$ all have $y = 0$, so the wall is the plane $y = 0$ (the $xz$-plane).`, d: 1, c: 'recall', t: [1], time: 30 }), (C) => { C.assert([[3, 0, 0], [0, 0, 4], [2, 0, -5]].every((p) => p[1] === 0), 'xz points'); C.key('a'); });
Q('m04', mk.mcq({ stem: r`A spotlight beam in a museum makes equal acute angles with the three coordinate axes. Its direction cosines are`, opts: [r`$\dfrac{1}{\sqrt3}, \dfrac{1}{\sqrt3}, \dfrac{1}{\sqrt3}$`, r`$\dfrac13, \dfrac13, \dfrac13$`, '$1, 1, 1$', r`$\dfrac{1}{\sqrt2}, \dfrac{1}{\sqrt2}, \dfrac{1}{\sqrt2}$`], key: 'a', sol: r`Equal angles give $l = m = n$ and $3l^2 = 1$, so $l = \dfrac{1}{\sqrt3}$ (positive for acute angles). The other triples do not have squares adding up to $1$.`, d: 2, c: 'understanding', t: [1], time: 45 }), (C) => C.which([[1 / Math.sqrt(3), 1 / Math.sqrt(3), 1 / Math.sqrt(3)], [1 / 3, 1 / 3, 1 / 3], [1, 1, 1], [Math.SQRT1_2, Math.SQRT1_2, Math.SQRT1_2]].map((u) => near(sumsq(u), 1)), true));
Q('m05', mk.mcq({ stem: r`A ropeway cable has direction cosines $l = \dfrac27$, $m = -\dfrac37$ and an unknown $n$. What are the possible values of $n$?`, opts: [r`$\pm\dfrac67$`, r`$\dfrac67$ only`, r`$\pm\dfrac57$`, r`$\pm 1$`], key: 'a', sol: r`$n^2 = 1 - \dfrac{4}{49} - \dfrac{9}{49} = \dfrac{36}{49}$, so $n = \pm\dfrac67$. Both signs give a valid direction; the sign depends on which way the cable is described.`, d: 2, c: 'application', t: [1], time: 60 }), (C) => C.which(['6/7,-6/7', '6/7', '5/7,-5/7', '1,-1'], [6, -6].filter((k) => near((2 / 7) ** 2 + (3 / 7) ** 2 + (k / 7) ** 2, 1)).map((k) => (k > 0 ? '6/7' : '-6/7')).join()));
const m06P = [3, 0, -2], m06Q = [6, 6, 0], m06R = [9, 12, 2];
Q('m06', mk.mcq({ stem: r`Three markers on a straight metro tunnel bore are at $P(3, 0, -2)$, $Q(6, 6, 0)$ and $R(9, 12, 2)$. What do the direction ratios of $PQ$ and $QR$ tell the engineer?`, opts: ['They are equal, so $P$, $Q$, $R$ are collinear', 'They are perpendicular, so the bore turns through a right angle at $Q$', 'They are not proportional, so the bore bends at $Q$', '$P$, $Q$, $R$ form a triangle of area $6$'], key: 'a', sol: r`$PQ$: $3, 6, 2$ and $QR$: $3, 6, 2$. Equal (hence proportional) ratios through the common point $Q$ mean one straight line.`, d: 2, c: 'application', t: [1], time: 60 }), (C) => { C.assert(eqv(sub(m06Q, m06P), sub(m06R, m06Q)) && dot(sub(m06Q, m06P), sub(m06R, m06Q)) !== 0, 'collinear, not perpendicular'); C.key('a'); });

// ================================================================ MCQ — t02 angle between lines; perpendicular and parallel
