Q('m07', mk.mcq({ stem: r`Two laser beams at a science fair have direction ratios $2, 2, 1$ and $2, -1, -2$. The angle between the beams is`, opts: [r`$90^\circ$`, r`$0^\circ$`, r`$60^\circ$`, r`$45^\circ$`], key: 'a', sol: r`$a_1a_2 + b_1b_2 + c_1c_2 = 4 - 2 - 2 = 0$, so $\cos\theta = 0$ and the beams are perpendicular.`, d: 1, c: 'understanding', t: [2], time: 45 }), (C) => C.which([90, 0, 60, 45], deg(m07u, m07v)));
