const m09k = 7 / 2;
Q('m09', mk.mcq({ stem: r`For which value of $k$ is the line $\dfrac{x - 2}{3} = \dfrac{y + 1}{k} = \dfrac{z}{2}$ perpendicular to the line $\dfrac{x}{1} = \dfrac{y - 4}{2} = \dfrac{z + 3}{-5}$?`, opts: [r`$\dfrac72$`, r`$-\dfrac72$`, '$2$', r`$\dfrac{13}{2}$`], key: 'a', sol: r`$3(1) + k(2) + 2(-5) = 0 \Rightarrow 2k = 7 \Rightarrow k = \dfrac72$.`, d: 2, c: 'understanding', t: [2], time: 60 }), (C) => C.which([3.5, -3.5, 2, 6.5].map((k) => dot([3, k, 2], [1, 2, -5]) === 0), true));
Q('m10', mk.mcq({ stem: r`Two straight conveyor belts in a warehouse run along direction ratios $3, -6, 9$ and $-1, p, -3$. If the belts are parallel, $p$ equals`, opts: ['$2$', '$-2$', '$6$', r`$\dfrac12$`], key: 'a', sol: r`Parallel lines have proportional ratios: $\dfrac{-1}{3} = \dfrac{p}{-6} = \dfrac{-3}{9}$, so $p = 2$.`, d: 2, c: 'understanding', t: [2], time: 60 }), (C) => C.which([2, -2, 6, 0.5].map((p) => parallel([3, -6, 9], [-1, p, -3])), true));
const m11A = [0, 1, 2], m11B = [2, 3, 3], m11C = [1, 0, 0], m11D = [5, 3, 0];
const m11cos = Math.abs(dot(sub(m11B, m11A), sub(m11D, m11C))) / (norm(sub(m11B, m11A)) * norm(sub(m11D, m11C)));
Q('m11', mk.mcq({ stem: r`A hiking trail map shows a footbridge from $A(0, 1, 2)$ to $B(2, 3, 3)$ and a zipline from $C(1, 0, 0)$ to $D(5, 3, 0)$. The cosine of the acute angle between the footbridge and the zipline is`, opts: [r`$\dfrac{14}{15}$`, r`$\dfrac23$`, r`$\dfrac45$`, r`$\dfrac{1}{15}$`], key: 'a', sol: r`Ratios $2, 2, 1$ (length $3$) and $4, 3, 0$ (length $5$): $\cos\theta = \dfrac{8 + 6 + 0}{3 \times 5} = \dfrac{14}{15}$.`, d: 3, c: 'application', t: [2], time: 90 }), (C) => C.which([14 / 15, 2 / 3, 4 / 5, 1 / 15], m11cos));

// ================================================================ MCQ — t03 equations of a line
const m12a = [3, -1, 2], m12b = [2, 5, -1];
Q('m12', mk.mcq({ stem: r`A lift cable passes through the point $(3, -1, 2)$ and runs parallel to $2\hat{i} + 5\hat{j} - \hat{k}$. Its vector equation is`, opts: [`$${lineVec(m12a, m12b)}$`, `$${lineVec(m12b, m12a)}$`, `$${lineVec(m12a, [2, 5, 1])}$`, `$${lineVec([-3, 1, -2], m12b)}$`], key: 'a', sol: r`$\vec{r} = \vec{a} + \lambda\vec{b}$ with $\vec{a}$ the position vector of the given point and $\vec{b}$ the given direction. Option (b) swaps their roles.`, d: 1, c: 'understanding', t: [3], time: 45 }), (C) => C.which([[m12a, m12b], [m12b, m12a], [m12a, [2, 5, 1]], [[-3, 1, -2], m12b]].map(([a, b]) => onLine(m12a, a, b) && parallel(b, m12b) && onLine(add(m12a, m12b), a, b)), true));
const m13A = [4, 0, -3], m13B = [1, 2, 5], m13d = sub(m13B, m13A);
Q('m13', mk.mcq({ stem: r`A straight drainage pipe is laid from $(4, 0, -3)$ to $(1, 2, 5)$. Its Cartesian equations are`, opts: [`$${cart(m13A, m13d)}$`, `$${cart(m13A, m13B)}$`, `$${cart([-4, 0, 3], m13d)}$`, `$${cart(m13A, [3, 2, 8])}$`], key: 'a', sol: r`Direction ratios are the differences $1 - 4 = -3$, $2 - 0 = 2$, $5 - (-3) = 8$; use either point in the numerators. Option (d) loses the sign of $-3$.`, d: 2, c: 'understanding', t: [3], time: 60 }), (C) => C.which([[m13A, m13d], [m13A, m13B], [[-4, 0, 3], m13d], [m13A, [3, 2, 8]]].map(([a, b]) => onLine(m13A, a, b) && onLine(m13B, a, b)), true));
const m14a = [-2, 1, 4], m14b = [3, -2, 5];
Q('m14', mk.mcq({ stem: r`A rescue team plots a straight search line $${cart(m14a, m14b)}$. Which of these points lies on it?`, opts: ['$(4, -3, 14)$', '$(3, -2, 5)$', '$(-2, 1, -4)$', '$(1, -1, 10)$'], key: 'a', sol: r`For $(4, -3, 14)$: $\dfrac63 = \dfrac{-4}{-2} = \dfrac{10}{5} = 2$, the same value in each fraction. For $(1, -1, 10)$ the fractions are $1, 1, \dfrac65$.`, d: 2, c: 'understanding', t: [3], time: 60 }), (C) => C.which([[4, -3, 14], [3, -2, 5], [-2, 1, -4], [1, -1, 10]].map((P) => onLine(P, m14a, m14b)), true));
// (3 - x)/4 = (2y + 1)/6 = (z + 2)/(-3)  ->  (x - 3)/(-4) = (y + 1/2)/3 = (z + 2)/(-3)
Q('m15', mk.mcq({ stem: r`A cable run is given as $\dfrac{3 - x}{4} = \dfrac{2y + 1}{6} = \dfrac{z + 2}{-3}$. After writing it in standard form, its direction ratios are`, opts: ['$-4, 3, -3$', '$4, 6, -3$', '$4, 3, -3$', '$-4, 6, -3$'], key: 'a', sol: r`Make each coefficient $1$: $\dfrac{x - 3}{-4} = \dfrac{y + \frac12}{3} = \dfrac{z + 2}{-3}$. So the ratios are $-4, 3, -3$. Option (b) reads the denominators without this step.`, d: 3, c: 'application', t: [3], time: 75 }), (C) => {
  // points from the original form at parameter t: x = 3 - 4t, y = (6t - 1)/2, z = -3t - 2; difference t = 1 minus t = 0
  const P = (t) => [3 - 4 * t, (6 * t - 1) / 2, -3 * t - 2];
  C.which([[-4, 3, -3], [4, 6, -3], [4, 3, -3], [-4, 6, -3]].map((d) => parallel(d, sub(P(1), P(0)))), true);
});
const m16a = [1, 0, -3], m16b = [2, -1, 4];
Q('m16', mk.mcq({ stem: r`A tunnel-boring machine moves along $\vec{r} = \hat{i} - 3\hat{k} + \lambda(2\hat{i} - \hat{j} + 4\hat{k})$. The same path in Cartesian form is`, opts: [`$${cart(m16a, m16b)}$`, `$${cart(m16b, m16a)}$`, `$${cart([-1, 0, 3], m16b)}$`, `$${cart(m16a, [2, 1, 4])}$`], key: 'a', sol: r`The point is $(1, 0, -3)$ and the direction ratios are $2, -1, 4$; write $\dfrac{x - x_1}{a} = \dfrac{y - y_1}{b} = \dfrac{z - z_1}{c}$.`, d: 2, c: 'understanding', t: [3], time: 60 }), (C) => C.which([[m16a, m16b], [m16b, m16a], [[-1, 0, 3], m16b], [m16a, [2, 1, 4]]].map(([a, b]) => onLine(m16a, a, b) && parallel(b, m16b)), true));

// ================================================================ MCQ — t04 coplanar, skew, intersection, point-to-line distance
Q('m17', mk.mcq({ stem: r`Two straight steel cables in a stadium roof are not parallel and never meet. Such a pair of lines is called`, opts: ['skew', 'coplanar and intersecting', 'concurrent', 'coincident'], key: 'a', sol: 'Lines in space that are neither parallel nor intersecting do not lie in one plane; they are skew lines.', d: 1, c: 'recall', t: [4], time: 30 }), (C) => { C.assert(!parallel([0, 1, 0], [1, 0, 0]) && intersect([1, 0, 0], [0, 1, 0], [0, 0, 5], [1, 0, 0]) === null, 'example pair skew'); C.key('a'); });
