Q('m18', mk.mcq({ stem: r`The flight paths $${lineVec(m18a1, m18b1)}$ and $${lineVec(m18a2, m18b2, '\\mu')}$ of two model aircraft cross each other. At which point?`, opts: ['$(3, 0, 7)$', '$(4, 1, 7)$', '$(2, 1, 5)$', '$(3, 1, 7)$'], key: 'a', sol: r`Equate components: $1 + \lambda = 4 + \mu$, $2 - \lambda = 1 + \mu$, $3 + 2\lambda = 7$. The third gives $\lambda = 2$, the second $\mu = -1$, and the first checks: $3 = 3$. The point is $(3, 0, 7)$.`, d: 3, c: 'application', t: [4], time: 90 }), (C) => C.which([[3, 0, 7], [4, 1, 7], [2, 1, 5], [3, 1, 7]].map((P) => onLine(P, m18a1, m18b1) && onLine(P, m18a2, m18b2)), true));
Q('m19', mk.mcq({ stem: r`Lines $\vec{r} = \vec{a}_1 + \lambda\vec{b}_1$ and $\vec{r} = \vec{a}_2 + \mu\vec{b}_2$ have non-parallel directions. Which condition tells a designer that the two lines lie in one plane, so that they meet?`, opts: [r`$(\vec{a}_2 - \vec{a}_1) \cdot (\vec{b}_1 \times \vec{b}_2) = 0$`, r`$\vec{b}_1 \cdot \vec{b}_2 = 0$`, r`$\vec{b}_1 \times \vec{b}_2 = \vec{0}$`, r`$|\vec{a}_2 - \vec{a}_1| = 0$`], key: 'a', sol: r`The lines are coplanar when $\vec{a}_2 - \vec{a}_1$, $\vec{b}_1$ and $\vec{b}_2$ lie in one plane, i.e. their scalar triple product is $0$. Option (b) is perpendicularity and (c) is parallelism.`, d: 2, c: 'understanding', t: [4], time: 60 }), (C) => { C.assert(near(dot(sub(m18a2, m18a1), cross(m18b1, m18b2)), 0) && m18X !== null, 'meeting pair has zero triple product'); C.key('a'); });
