must(m20F.t === 3 && eqv(m20F.F, [4, 6, 5]), 'm20 foot');
Q('m20', mk.mcq({ stem: r`A lamp at $P(4, 4, 7)$ hangs near a straight rail $${cart(m20a, m20b)}$. The foot of the perpendicular from the lamp to the rail is`, opts: ['$(4, 6, 5)$', '$(2, 2, 1)$', '$(4, 4, 7)$', '$(3, 6, 5)$'], key: 'a', sol: r`A general rail point is $(1 + \lambda, 2\lambda, -1 + 2\lambda)$. The joining vector $(\lambda - 3, 2\lambda - 4, 2\lambda - 8)$ is perpendicular to $(1, 2, 2)$: $9\lambda - 27 = 0$, so $\lambda = 3$ and the foot is $(4, 6, 5)$.`, d: 3, c: 'application', t: [4], time: 90 }), (C) => C.which([[4, 6, 5], [2, 2, 1], [4, 4, 7], [3, 6, 5]].map((F) => onLine(F, m20a, m20b) && near(dot(sub(m20P, F), m20b), 0)), true));

